-- Economics Gen2 T2 Practice rebalancing: 20 easy / 30 medium / 20 hard.
-- Original questions never deleted; originals with historical references remain resolvable.
-- New question versions carry their own complete trilingual content and per-option diagnostics.
-- Preconditions and postconditions are enforced transactionally. Run controlled QA transaction first.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '90s';
DO $reb$
DECLARE
  payload jsonb := '[{"ref":"EC9708:G2:EC9708-G2-T2-P-002","d":"hard","sec":180,"k":"C","en":"A bakery buys flour for $30, electricity for $10 and packaging for $5, then sells finished bread to a retailer for $100. The retailer sells that bread to households for $150 without other intermediate purchases. What is the combined value added at the bakery and retail stages?","ru":"Пекарня покупает муку за $30, электроэнергию за $10 и упаковку за $5, затем продаёт хлеб магазину за $100. Магазин продаёт хлеб покупателям за $150 без других промежуточных закупок. Какова общая добавленная стоимость пекарни и магазина?","uz":"Nonvoyxona unni $30, elektrni $10 va qadoqni $5 ga olib, tayyor nonni do‘konga $100 ga sotadi. Do‘kon boshqa oraliq xaridlarsiz nonni aholiga $150 ga sotadi. Nonvoyxona va do‘kon bosqichlaridagi jami qo‘shilgan qiymat qancha?","options_en":["$55","$150","$105","$95"],"options_ru":["$55","$150","$105","$95"],"options_uz":["$55","$150","$105","$95"],"why":["Bakery value added is $100 − ($30 + $10 + $5) = $55; retail value added is $150 − $100 = $50. Combined = $105.","Добавленная стоимость пекарни $100 − ($30 + $10 + $5) = $55, магазина $150 − $100 = $50. Всего $105.","Nonvoyxona qo‘shilgan qiymati $100 − ($30 + $10 + $5) = $55, do‘kon esa $150 − $100 = $50. Jami $105."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-003","d":"hard","sec":195,"k":"B","en":"In a short-run model, aggregate demand is Qd = 300 − P and aggregate supply is initially Qs = 100 + P. A permanent improvement in productivity raises short-run supply to Qs = 140 + P, with aggregate demand unchanged. How do equilibrium price and real output change?","ru":"В краткосрочной модели совокупный спрос Qd = 300 − P, первоначальное совокупное предложение Qs = 100 + P. Постоянный рост производительности изменяет краткосрочное предложение до Qs = 140 + P при неизменном спросе. Как меняются равновесный уровень цен и реальный выпуск?","uz":"Qisqa muddatli modelda yalpi talab Qd = 300 − P, dastlabki yalpi taklif Qs = 100 + P. Unumdorlikning doimiy oshishi qisqa muddatli taklifni Qs = 140 + P ga o‘zgartiradi, talab o‘zgarmaydi. Muvozanat narx darajasi va real ishlab chiqarish qanday o‘zgaradi?","options_en":["Price +20; output −20","Price −20; output +20","Price −40; output +40","Price unchanged; output +40"],"options_ru":["Уровень цен +20; выпуск −20","Уровень цен −20; выпуск +20","Уровень цен −40; выпуск +40","Уровень цен неизменен; выпуск +40"],"options_uz":["Narx darajasi +20; ishlab chiqarish −20","Narx darajasi −20; ishlab chiqarish +20","Narx darajasi −40; ishlab chiqarish +40","Narx darajasi o‘zgarmaydi; ishlab chiqarish +40"],"why":["Initially P = 100 and Q = 200. Afterwards P = 80 and Q = 220. The supply expansion lowers price by 20 and raises output by 20.","Изначально P = 100, Q = 200. Затем P = 80, Q = 220: цены −20, выпуск +20.","Dastlab P = 100, Q = 200. Keyin P = 80, Q = 220: narx −20, ishlab chiqarish +20."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-004","d":"hard","sec":170,"k":"D","en":"A consumer price index starts at 100. Inflation is 8% in year 1 and 3% in year 2. Assuming the index uses the previous year''s level as the base each year, what is the price index at the end of year 2, and how is year-2 inflation best described?","ru":"Индекс потребительских цен изначально равен 100. Инфляция составляет 8% в первом году и 3% во втором. Если каждый процент применяется к уровню цен предыдущего года, чему равен индекс в конце второго года и как характеризуется инфляция во втором году?","uz":"Iste’mol narxlari indeksi boshida 100. Birinchi yilda inflyatsiya 8%, ikkinchisida 3%. Har yilgi foiz oldingi yil narx darajasiga qo‘llansa, ikkinchi yil oxiridagi indeks qancha va ikkinchi yil inflyatsiyasi qanday ataladi?","options_en":["111; deflation","103; disinflation","111.24; deflation","111.24; disinflation"],"options_ru":["111; дефляция","103; дезинфляция","111,24; дефляция","111,24; дезинфляция"],"options_uz":["111; deflyatsiya","103; dezinflyatsiya","111,24; deflyatsiya","111,24; dezinflyatsiya"],"why":["The index becomes 100×1.08×1.03 = 111.24. Inflation remains positive but slows, which is disinflation, not deflation.","Индекс равен 100×1,08×1,03 = 111,24. Темп инфляции остаётся положительным, но замедляется: это дезинфляция.","Indeks 100×1,08×1,03 = 111,24. Inflyatsiya musbat, ammo sur’ati pasaygan: bu dezinflyatsiya."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-005","d":"hard","sec":195,"k":"A","en":"Domestic demand is Qd = 500 − 2P and short-run aggregate supply is initially Qs = 100 + 2P. Imported raw-material costs rise and shift supply to Qs = 60 + 2P, while demand is unchanged. Relative to the original equilibrium, what happens?","ru":"Совокупный спрос Qd = 500 − 2P, первоначальное краткосрочное предложение Qs = 100 + 2P. Подорожание импортного сырья изменяет предложение на Qs = 60 + 2P при неизменном спросе. Что происходит относительно первоначального равновесия?","uz":"Yalpi talab Qd = 500 − 2P, dastlabki qisqa muddatli taklif Qs = 100 + 2P. Import xomashyosi qimmatlashib, taklif Qs = 60 + 2P ga siljiydi, talab o‘zgarmaydi. Avvalgi muvozanatga nisbatan nima yuz beradi?","options_en":["Price +10; real output −20","Price −10; real output +20","Price +20; real output unchanged","Price unchanged; real output −40"],"options_ru":["Уровень цен +10; реальный выпуск −20","Уровень цен −10; реальный выпуск +20","Уровень цен +20; реальный выпуск неизменен","Уровень цен неизменен; реальный выпуск −40"],"options_uz":["Narx darajasi +10; real ishlab chiqarish −20","Narx darajasi −10; real ishlab chiqarish +20","Narx darajasi +20; real ishlab chiqarish o‘zgarmaydi","Narx darajasi o‘zgarmaydi; real ishlab chiqarish −40"],"why":["Initially P = 100 and Q = 300; after the cost shock P = 110 and Q = 280. This is cost-push inflation with lower output.","Изначально P = 100, Q = 300, после шока P = 110, Q = 280. Рост издержек вызывает повышение цен и снижение выпуска.","Dastlab P = 100, Q = 300, shokdan so‘ng P = 110, Q = 280. Xarajatlar oshishi narxni ko‘tarib, ishlab chiqarishni kamaytiradi."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-007","d":"hard","sec":170,"k":"C","en":"An economy initially has C = $430m, I = $120m, G = $180m, X = $80m and M = $110m. Next year government purchases rise by $30m, but imports also rise by $20m; all other components stay fixed. What are initial AD and new AD in the expenditure model?","ru":"Первоначально в экономике C = $430 млн, I = $120 млн, G = $180 млн, X = $80 млн, M = $110 млн. В следующем году государственные закупки растут на $30 млн, а импорт — на $20 млн; прочие составляющие неизменны. Найдите первоначальный и новый совокупный спрос по расходной модели.","uz":"Iqtisodiyotda dastlab C = $430 mln, I = $120 mln, G = $180 mln, X = $80 mln, M = $110 mln. Keyingi yili davlat xaridlari $30 mln, import esa $20 mln ga oshadi; boshqa tarkibiy qismlar o‘zgarmaydi. Xarajat modelidagi dastlabki va yangi yalpi talab qancha?","options_en":["$700m → $750m","$810m → $820m","$700m → $710m","$700m → $690m"],"options_ru":["$700m → $750m","$810m → $820m","$700m → $710m","$700m → $690m"],"options_uz":["$700m → $750m","$810m → $820m","$700m → $710m","$700m → $690m"],"why":["AD = C + I + G + X − M = 700. A +30 change in G and +20 change in imports produces a net +10, so AD = 710.","AD = C + I + G + X − M = 700. G +30 и импорт +20 дают чистое изменение +10: новый AD = 710.","AD = C + I + G + X − M = 700. G +30, import +20 bo‘lsa sof +10; yangi AD = 710."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-010","d":"hard","sec":190,"k":"B","en":"Two households each earn $40,000 annually. Household A owns a house worth $200,000, while household B owns net assets of $30,000. House prices rise 10%, affecting only A''s house, and both wages rise 5%. Other wealth components are fixed. How do their annual income gap and net-wealth gap change?","ru":"Два домохозяйства получают по $40 000 дохода в год. A владеет домом за $200 000, B — чистыми активами на $30 000. Цены на дома растут на 10%, затрагивая только дом A, а зарплаты обоих растут на 5%. Прочие активы неизменны. Как меняются разрыв доходов и разрыв чистого богатства?","uz":"Ikki uy xo‘jaligining har biri yiliga $40 000 topadi. A ning uyi $200 000, B ning sof aktivlari $30 000. Uy narxlari 10% ga oshib, faqat A uyiga ta’sir qiladi, ikkala ish haqi 5% ga oshadi. Boshqa aktivlar o‘zgarmaydi. Daromad va sof boylik tafovuti qanday o‘zgaradi?","options_en":["Income gap +$2,000; wealth gap unchanged","Income gap unchanged; wealth gap +$20,000","Income gap +$4,000; wealth gap +$20,000","Income gap unchanged; wealth gap −$20,000"],"options_ru":["Разрыв доходов +$2 000; разрыв богатства неизменен","Разрыв доходов неизменен; разрыв богатства +$20 000","Разрыв доходов +$4 000; разрыв богатства +$20 000","Разрыв доходов неизменен; разрыв богатства −$20 000"],"options_uz":["Daromad tafovuti +$2000; boylik tafovuti o‘zgarmaydi","Daromad tafovuti o‘zgarmaydi; boylik tafovuti +$20 000","Daromad tafovuti +$4000; boylik tafovuti +$20 000","Daromad tafovuti o‘zgarmaydi; boylik tafovuti −$20 000"],"why":["Both incomes grow equally, leaving a zero income gap. A''s house appreciates by $20,000, widening the wealth gap by $20,000.","Доходы остаются равными. Дом A дорожает на $20 000, поэтому разрыв богатства растёт на $20 000.","Ikkala daromad teng oshadi, tafovut nol. A uyi $20 000 ga qimmatlashib, boylik tafovutini $20 000 ga kengaytiradi."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-012","d":"hard","sec":175,"k":"D","en":"Real GDP rises from $240bn to $252bn in one year, while population rises from 20 million to 21 million. Assuming both figures cover the same period, approximately how much does real GDP per person grow?","ru":"Реальный ВВП за год вырос с $240 млрд до $252 млрд, а население — с 20 млн до 21 млн. Если оба изменения относятся к одному периоду, на сколько примерно вырос реальный ВВП на человека?","uz":"Real YaIM bir yilda $240 mlrd dan $252 mlrd ga, aholi esa 20 mln dan 21 mln ga oshdi. Ikkala o‘zgarish bir davrga tegishli bo‘lsa, aholi jon boshiga real YaIM taxminan necha foiz oshdi?","options_en":["10%","5%","2.5%","0%"],"options_ru":["10%","5%","2.5%","0%"],"options_uz":["10%","5%","2.5%","0%"],"why":["GDP grows 5%, but population also grows 5%. Per-person GDP is $12,000 in both years, so growth is zero.","ВВП и население увеличились на 5%. ВВП на человека в обоих годах $12 000, прирост 0%.","YaIM va aholi har biri 5% ga oshgan. Jon boshiga YaIM ikki yilda ham $12 000; o‘sish 0%."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-013","d":"hard","sec":185,"k":"C","en":"A country has GDP of $560bn. Domestic residents receive $18bn primary income from overseas while non-residents earn $38bn primary income domestically. Consumption of fixed capital is $30bn. What is net national income (NNI)?","ru":"ВВП страны составляет $560 млрд. Резиденты получают $18 млрд первичных доходов из-за рубежа, нерезиденты зарабатывают внутри страны $38 млрд. Потребление основного капитала составляет $30 млрд. Найдите чистый национальный доход (NNI).","uz":"Mamlakat YaIMi $560 mlrd. Rezidentlar chet eldan $18 mlrd birlamchi daromad oladi, norezidentlar mamlakat ichida $38 mlrd ishlab topadi. Asosiy kapital iste’moli $30 mlrd. Sof milliy daromad (NNI) qancha?","options_en":["$530bn","$550bn","$510bn","$590bn"],"options_ru":["$530bn","$550bn","$510bn","$590bn"],"options_uz":["$530bn","$550bn","$510bn","$590bn"],"why":["Net primary income from abroad is 18 − 38 = −20. GNI = 560 − 20 = 540; NNI = 540 − 30 = 510.","Чистые первичные доходы из-за рубежа: 18 − 38 = −20. GNI = 540, NNI = 540 − 30 = 510.","Chet eldan sof birlamchi daromad 18 − 38 = −20. YAMD = 540, NNI = 540 − 30 = 510."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-014","d":"hard","sec":170,"k":"A","en":"A screening service costs $40 per person. Families mistakenly perceive only $20 private benefit, although the actual private benefit is $45 and benefits to others add $10. Which statement is best supported by the figures?","ru":"Профилактическое обследование стоит $40 на человека. Семьи ошибочно оценивают личную выгоду лишь в $20, хотя фактическая личная выгода $45 и польза другим людям ещё $10. Какой вывод наиболее обоснован данными?","uz":"Profilaktik tekshiruv kishi boshiga $40 turadi. Oilalar shaxsiy foydani xato ravishda $20 deb biladi, asl shaxsiy foyda $45 va boshqalarga qo‘shimcha foyda $10. Qaysi xulosa ma’lumotlarga mos?","options_en":["Better information alone could make private willingness to pay exceed cost, while external benefits still exist.","Better information necessarily eliminates the external benefit.","Actual total social benefit is only $20.","The service is socially inefficient because its price exceeds perceived private benefit."],"options_ru":["Более полная информация сама по себе может поднять личную готовность платить выше затрат, при сохранении внешних выгод.","Более полная информация обязательно устраняет внешние выгоды.","Фактическая общая общественная выгода равна только $20.","Услуга неэффективна для общества, поскольку её цена выше субъективной личной выгоды."],"options_uz":["To‘liqroq axborot shaxsiy to‘lashga tayyorlikni xarajatdan yuqoriga olib chiqishi mumkin, tashqi foyda esa qoladi.","To‘liqroq axborot tashqi foydani albatta yo‘q qiladi.","Haqiqiy umumiy ijtimoiy foyda atigi $20.","Bahosi xato baholangan shaxsiy foydadan yuqori bo‘lgani uchun xizmat jamiyat uchun samarasiz."],"why":["Perceived private benefit ($20) is below cost ($40), but actual private benefit ($45) exceeds it, even before the $10 external benefit. Information can therefore alter demand.","Субъективная выгода $20 ниже затрат $40, но реальная личная выгода $45 выше затрат даже без внешней пользы $10. Информация способна изменить спрос.","His qilingan foyda $20 xarajat $40 dan past, asl shaxsiy foyda $45 esa yuqori, $10 tashqi foydadan tashqari. Axborot talabni o‘zgartirishi mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-016","d":"hard","sec":200,"k":"B","en":"Before policy, the annual incomes of high- and low-income households are $1,000 and $200 respectively. The high-income household pays $200 tax; the low-income household receives $150 transfer. Ignore other responses. How much does the gap between their disposable incomes narrow?","ru":"До вмешательства годовые доходы богатого и бедного домохозяйств равны $1 000 и $200. Богатое домохозяйство платит $200 налога, бедное получает трансферт $150. Игнорируйте другие реакции. На сколько сужается разница их располагаемых доходов?","uz":"Siyosatgacha yuqori va past daromadli xonadonlar yiliga mos ravishda $1000 va $200 topadi. Boyroq xonadon $200 soliq to‘laydi, kambag‘al xonadon $150 transfer oladi. Boshqa ta’sirlarni e’tiborga olmang. Ularning ixtiyoridagi daromad tafovuti qanchaga qisqaradi?","options_en":["$150","$350","$200","$450"],"options_ru":["$150","$350","$200","$450"],"options_uz":["$150","$350","$200","$450"],"why":["Initially the gap is $800. Afterwards disposable incomes are $800 and $350, gap $450. Narrowing = $350.","Изначальный разрыв $800. Затем располагаемые доходы $800 и $350, разрыв $450. Сужение $350.","Dastlab farq $800. Keyin ixtiyordagi daromadlar $800 va $350, farq $450. Qisqarish $350."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-018","d":"hard","sec":185,"k":"A","en":"Nominal GDP rises by 12%, the GDP deflator rises by 8%, and population rises by 2% over the same year. Using exact index ratios, approximately what is the growth rate of real GDP per person?","ru":"За один год номинальный ВВП вырос на 12%, дефлятор ВВП — на 8%, население — на 2%. Используя точные отношения индексов, оцените темп роста реального ВВП на человека.","uz":"Bir yilda nominal YaIM 12% ga, YaIM deflyatori 8% ga, aholi 2% ga oshdi. Indekslarning aniq nisbatlaridan foydalanib, jon boshiga real YaIM o‘sishini taxminan toping.","options_en":["+1.67%","+2.00%","+3.70%","+4.00%"],"options_ru":["+1.67%","+2.00%","+3.70%","+4.00%"],"options_uz":["+1.67%","+2.00%","+3.70%","+4.00%"],"why":["Real GDP grows 1.12/1.08 − 1 ≈ 3.70%. Per person, growth is (1.12/1.08)/1.02 − 1 ≈ 1.67%.","Реальный ВВП растёт на 1,12/1,08 − 1 ≈ 3,70%. На человека: (1,12/1,08)/1,02 − 1 ≈ 1,67%.","Real YaIM o‘sishi 1,12/1,08 − 1 ≈ 3,70%. Jon boshiga: (1,12/1,08)/1,02 − 1 ≈ 1,67%."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-019","d":"hard","sec":170,"k":"C","en":"In a simplified open-economy circular flow, investment is $40m, government spending $50m and exports $30m. Savings are $35m, taxes $45m and imports $50m. With spare capacity and otherwise normal adjustment, which statement follows?","ru":"В упрощённом круговом потоке открытой экономики инвестиции — $40 млн, госрасходы — $50 млн, экспорт — $30 млн. Сбережения — $35 млн, налоги — $45 млн, импорт — $50 млн. При наличии резервных мощностей какой вывод следует в модели обычной корректировки?","uz":"Ochiq iqtisodiyotning soddalashtirilgan aylanishida investitsiya $40 mln, davlat xarajati $50 mln, eksport $30 mln. Jamg‘arma $35 mln, soliqlar $45 mln, import $50 mln. Bo‘sh quvvat mavjud bo‘lsa, odatiy moslashuvda qaysi xulosa kelib chiqadi?","options_en":["Injections exceed leakages by $10m, creating upward pressure on income.","Injections and leakages are equal, so income is stable.","Leakages exceed injections by $10m, tending to reduce income.","The current account is balanced because government spending is $50m."],"options_ru":["Инъекции превышают изъятия на $10 млн, стимулируя рост дохода.","Инъекции и изъятия равны, поэтому доход стабилен.","Изъятия превышают инъекции на $10 млн, создавая тенденцию к снижению дохода.","Текущий счёт сбалансирован, потому что госрасходы $50 млн."],"options_uz":["Inyeksiyalar chiqimlardan $10 mln ko‘p, daromad oshishga intiladi.","Inyeksiya va chiqimlar teng; daromad barqaror.","Chiqimlar inyeksiyalardan $10 mln ko‘p, daromad kamayishga intiladi.","Davlat xarajati $50 mln bo‘lgani uchun joriy hisob muvozanatli."],"why":["Injections = 40 + 50 + 30 = 120; leakages = 35 + 45 + 50 = 130. A net withdrawal of $10m tends to depress income.","Инъекции 40 + 50 + 30 = 120; изъятия 35 + 45 + 50 = 130. Чистое изъятие $10 млн сокращает совокупный доход.","Inyeksiyalar 120, chiqimlar 130. $10 mln sof chiqim milliy daromadni kamaytirishga moyil."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-023","d":"hard","sec":205,"k":"D","en":"Demand is Qd = 200 − 2Pb and supply is Qs = 40 + 2Ps. The government pays producers a subsidy of $10 per unit, so Ps = Pb + 10, where Pb is the price paid by buyers and Ps received by sellers. Compared with no subsidy, what happens to the two prices and the equilibrium quantity?","ru":"Спрос Qd = 200 − 2Pb, предложение Qs = 40 + 2Ps. Государство выплачивает производителям субсидию $10 на единицу, поэтому Ps = Pb + 10, где Pb — цена для покупателя, Ps — доходная цена продавца. Что изменится относительно рынка без субсидии?","uz":"Talab Qd = 200 − 2Pb, taklif Qs = 40 + 2Ps. Davlat ishlab chiqaruvchilarga birlik uchun $10 subsidiya beradi, shuning uchun Ps = Pb + 10; Pb xaridor narxi, Ps sotuvchi oladigan narx. Subsidiyasiz holatga nisbatan ikki narx va miqdor qanday o‘zgaradi?","options_en":["Buyers pay $45, sellers get $35, quantity falls.","Buyers pay $40, sellers get $50, quantity remains unchanged.","Buyers pay $30, sellers get $40, quantity rises by 20.","Buyers pay $35, sellers get $45, quantity rises by 10."],"options_ru":["Покупатели платят $45, продавцы получают $35, объём падает.","Покупатели платят $40, продавцы получают $50, объём неизменен.","Покупатели платят $30, продавцы получают $40, объём растёт на 20.","Покупатели платят $35, продавцы получают $45, объём растёт на 10."],"options_uz":["Xaridorlar $45 to‘laydi, sotuvchilar $35 oladi, miqdor kamayadi.","Xaridorlar $40 to‘laydi, sotuvchilar $50 oladi, miqdor o‘zgarmaydi.","Xaridorlar $30 to‘laydi, sotuvchilar $40 oladi, miqdor 20 ga oshadi.","Xaridorlar $35 to‘laydi, sotuvchilar $45 oladi, miqdor 10 ga oshadi."],"why":["Without subsidy P = 40 and Q = 120. With subsidy 200−2Pb = 40+2(Pb+10) gives Pb = 35, Ps = 45, Q = 130.","Без субсидии P = 40, Q = 120. При субсидии 200−2Pb = 40+2(Pb+10), отсюда Pb = 35, Ps = 45, Q = 130.","Subsidiyasiz P = 40, Q = 120. Subsidiya bilan 200−2Pb = 40+2(Pb+10); Pb = 35, Ps = 45, Q = 130."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-024","d":"hard","sec":180,"k":"C","en":"A country reports gross value added at basic prices of $800bn, product taxes of $55bn, product subsidies of $15bn and depreciation of $60bn. What are GDP at market prices and net domestic product at market prices?","ru":"В стране валовая добавленная стоимость в основных ценах $800 млрд, налоги на продукты $55 млрд, субсидии на продукты $15 млрд, амортизация $60 млрд. Найдите ВВП и чистый внутренний продукт в рыночных ценах.","uz":"Mamlakatda asosiy narxlarda yalpi qo‘shilgan qiymat $800 mlrd, mahsulot soliqlari $55 mlrd, subsidiyalar $15 mlrd va amortizatsiya $60 mlrd. Bozor narxlaridagi YaIM va sof ichki mahsulot qancha?","options_en":["GDP $870bn; NDP $810bn","GDP $840bn; NDP $800bn","GDP $840bn; NDP $780bn","GDP $760bn; NDP $700bn"],"options_ru":["GDP $870bn; NDP $810bn","GDP $840bn; NDP $800bn","GDP $840bn; NDP $780bn","GDP $760bn; NDP $700bn"],"options_uz":["GDP $870bn; NDP $810bn","GDP $840bn; NDP $800bn","GDP $840bn; NDP $780bn","GDP $760bn; NDP $700bn"],"why":["GDP = 800 + 55 − 15 = 840. NDP deducts depreciation: 840 − 60 = 780.","ВВП = 800 + 55 − 15 = 840. Чистый внутренний продукт 840 − 60 = 780.","YaIM = 800 + 55 − 15 = 840. Sof ichki mahsulot 840 − 60 = 780."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-027","d":"hard","sec":175,"k":"A","en":"In a simplified long-run AD–AS model, aggregate demand is Qd = 400 − 2P while vertical LRAS initially fixes real capacity at Q = 200. Productivity improvement shifts LRAS to Q = 220, with aggregate demand unchanged. What is the new price level and output?","ru":"В упрощённой долгосрочной модели AD–AS совокупный спрос Qd = 400 − 2P, вертикальная LRAS первоначально фиксирует выпуск Q = 200. Рост производительности сдвигает LRAS к Q = 220 при неизменном AD. Каковы новые уровень цен и выпуск?","uz":"Soddalashtirilgan uzoq muddatli AD–AS modelida yalpi talab Qd = 400 − 2P, vertikal LRAS dastlab Q = 200 ni belgilaydi. Unumdorlik o‘sishi LRAS ni Q = 220 ga siljitadi, AD o‘zgarmaydi. Yangi narx darajasi va ishlab chiqarish qancha?","options_en":["P = 90; Q = 220","P = 110; Q = 220","P = 100; Q = 220","P = 90; Q = 200"],"options_ru":["P = 90; Q = 220","P = 110; Q = 220","P = 100; Q = 220","P = 90; Q = 200"],"options_uz":["P = 90; Q = 220","P = 110; Q = 220","P = 100; Q = 220","P = 90; Q = 200"],"why":["Initially 200 = 400 − 2P yields P = 100. New capacity 220 = 400 − 2P yields P = 90 and Q = 220.","Изначально P = 100. При новом потенциальном выпуске 220 = 400 − 2P, откуда P = 90, Q = 220.","Dastlab P = 100. Yangi quvvatda 220 = 400 − 2P, natija P = 90, Q = 220."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-031","d":"hard","sec":180,"k":"D","en":"Initially, aggregate demand is Qd = 400 − 2P. The price index is 100. A rise in consumer confidence shifts demand to Qd = 440 − 2P and the price index subsequently falls to 90. By how much does quantity demanded change in total, and how much is due to movement along the NEW curve caused by the price fall?","ru":"Первоначальный AD описан Qd = 400 − 2P, индекс цен равен 100. Улучшение доверия потребителей сдвигает AD к Qd = 440 − 2P, после чего индекс цен снижается до 90. На сколько изменится объём спроса в целом и какая часть связана с движением вдоль НОВОЙ кривой при снижении цен?","uz":"Dastlab yalpi talab Qd = 400 − 2P, narx indeksi 100. Iste’molchi ishonchi oshib, talab Qd = 440 − 2P ga siljiydi, keyin narx indeksi 90 ga tushadi. Jami talab miqdori qanchaga o‘zgaradi va yangi egri chiziq bo‘ylab narx pasayishi hisobiga qancha?","options_en":["Total +20; movement +40","Total +40; movement +40","Total +60; movement +40","Total +60; movement +20"],"options_ru":["Всего +20; движение +40","Всего +40; движение +40","Всего +60; движение +40","Всего +60; движение +20"],"options_uz":["Jami +20; egri chiziq bo‘ylab +40","Jami +40; egri chiziq bo‘ylab +40","Jami +60; egri chiziq bo‘ylab +40","Jami +60; egri chiziq bo‘ylab +20"],"why":["Initially Q = 200. A shift at P = 100 adds 40, giving 240. A fall in P to 90 adds another 20 along the new curve; final Q = 260.","Сначала Q = 200. Сдвиг при P = 100 добавляет 40, затем снижение P до 90 — ещё 20 вдоль новой кривой. Всего +60.","Dastlab Q = 200. Siljish P = 100 da +40 beradi, keyingi P = 90 ga tushish yangi egri chiziq bo‘ylab +20. Jami +60."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-038","d":"hard","sec":190,"k":"B","en":"A buffer-stock agency maintains grain prices between $8 and $12. At the floor price of $8, market supply is 170 tonnes and private demand is 100 tonnes. Months later, at the ceiling price of $12, private demand is 110 tonnes and private supply is 75 tonnes. What quantity must the agency buy first and release from stock later to support those respective prices, ignoring storage losses?","ru":"Агентство буферных запасов удерживает цену зерна между $8 и $12. При нижней цене $8 рыночное предложение 170 тонн, частный спрос 100 тонн. Через несколько месяцев при верхней цене $12 частный спрос 110 тонн, частное предложение 75 тонн. Сколько агентству нужно сначала закупить и затем выпустить из запасов, чтобы поддержать соответствующие цены, игнорируя потери хранения?","uz":"Bufer zaxira agentligi don narxini $8–$12 oralig‘ida ushlab turadi. $8 pastki narxda bozor taklifi 170 tonna, xususiy talab 100 tonna. Keyin $12 yuqori narxda xususiy talab 110, taklif 75 tonna bo‘ladi. Saqlashdagi yo‘qotishsiz agentlik avval qancha sotib olib, keyin qancha zaxiradan chiqarishi kerak?","options_en":["Buy 35; release 70 tonnes","Buy 70; release 35 tonnes","Buy 70; release 70 tonnes","Buy 170; release 110 tonnes"],"options_ru":["Купить 35; выпустить 70 тонн","Купить 70; выпустить 35 тонн","Купить 70; выпустить 70 тонн","Купить 170; выпустить 110 тонн"],"options_uz":["35 tonna sotib olish; 70 tonna chiqarish","70 tonna sotib olish; 35 tonna chiqarish","70 tonna sotib olish; 70 tonna chiqarish","170 tonna sotib olish; 110 tonna chiqarish"],"why":["At the floor, excess supply = 170 − 100 = 70, which the agency buys. At the ceiling, shortage = 110 − 75 = 35, which it releases.","При нижней цене излишек 170 − 100 = 70 тонн, его агентство покупает. При верхней цене дефицит 110 − 75 = 35 тонн, его покрывают запасами.","Pastki narxda ortiqcha taklif 170 − 100 = 70 tonna sotib olinadi. Yuqori narxda yetishmovchilik 110 − 75 = 35 tonna zaxiradan chiqariladi."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-041","d":"hard","sec":170,"k":"C","en":"A legal minimum milk price of $12 is above equilibrium. At that price, farmers offer 140 units while consumers want 80. The government purchases 45 unsold units at $12. How many units remain unsold by both private buyers and government, and what is the government purchase cost?","ru":"Обязательная минимальная цена молока $12 выше равновесной. По этой цене фермеры предлагают 140 единиц, покупатели хотят 80. Государство выкупает 45 непроданных единиц по $12. Сколько единиц останутся непроданными и сколько стоит госзакупка?","uz":"Sutning qonuniy eng kam narxi $12 bo‘lib, muvozanatdan yuqori. Bu narxda fermerlar 140 birlik taklif qiladi, iste’molchilar 80 birlik xohlaydi. Davlat sotilmagan 45 birlikni $12 dan xarid qiladi. Qancha birlik sotilmay qoladi va davlat xarajati qancha?","options_en":["60 units; $540","15 units; $180","15 units; $540","45 units; $540"],"options_ru":["60 единиц; $540","15 единиц; $180","15 единиц; $540","45 единиц; $540"],"options_uz":["60 birlik; $540","15 birlik; $180","15 birlik; $540","45 birlik; $540"],"why":["Initial surplus is 140 − 80 = 60 units; buying 45 leaves 15 unsold. Government spending is 45 × $12 = $540.","Первоначальный излишек 140 − 80 = 60, выкуп 45 оставляет 15. Госзатраты 45 × $12 = $540.","Ortiqcha taklif 140 − 80 = 60, 45 ta davlat xarididan so‘ng 15 ta qoladi. Xarajat 45 × $12 = $540."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-049","d":"hard","sec":185,"k":"A","en":"An imported-fuel cost shock raises the consumer price index from 100 to 110 and reduces real output. A household''s nominal wage rises by only 5% over the same period. What is the approximate change in its real wage, and which inflation mechanism is most consistent with the shock?","ru":"Рост стоимости импортного топлива повышает индекс потребительских цен со 100 до 110 и снижает реальный выпуск. Номинальная зарплата домохозяйства выросла за тот же период лишь на 5%. Как примерно изменилась его реальная зарплата и какой инфляционный механизм соответствует шоку?","uz":"Import yoqilg‘i xarajati oshib, iste’mol narxlari indeksi 100 dan 110 ga ko‘tariladi va real ishlab chiqarish kamayadi. Shu davrda xonadonning nominal ish haqi faqat 5% ga oshdi. Real ish haqi taxminan qanchaga o‘zgardi va bu qanday inflyatsiya mexanizmi?","options_en":["Real wage −4.5%; cost-push inflation","Real wage +5%; demand-pull inflation","Real wage −10%; demand-pull inflation","Real wage −5%; purely monetary inflation"],"options_ru":["Реальная зарплата −4,5%; инфляция издержек","Реальная зарплата +5%; инфляция спроса","Реальная зарплата −10%; инфляция спроса","Реальная зарплата −5%; исключительно монетарная инфляция"],"options_uz":["Real ish haqi −4,5%; xarajatlar inflyatsiyasi","Real ish haqi +5%; talab inflyatsiyasi","Real ish haqi −10%; talab inflyatsiyasi","Real ish haqi −5%; faqat monetar inflyatsiya"],"why":["The real wage factor is 1.05/1.10 ≈ 0.9545, a 4.5% fall. Imported input-cost pressure with lower output is cost-push inflation.","Реальная зарплата: 1,05/1,10 ≈ 0,9545, то есть снижение на 4,5%. Рост импортных затрат при сокращении выпуска — инфляция издержек.","Real ish haqi 1,05/1,10 ≈ 0,9545, ya’ni 4,5% kamayish. Import xarajatlari oshib, ishlab chiqarish tushishi — xarajatlar inflyatsiyasi."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-059","d":"hard","sec":200,"k":"D","en":"A labour force initially has 2.4 million employed and 0.3 million unemployed actively seeking work; another 0.5 million people are inactive. Then 0.1 million unemployed stop searching but no one gets a job. What happens to the measured unemployment rate?","ru":"В рабочей силе первоначально 2,4 млн занятых и 0,3 млн безработных, активно ищущих работу; ещё 0,5 млн экономически неактивны. Затем 0,1 млн безработных прекращают поиски, хотя никто не устроился на работу. Как изменится измеряемый уровень безработицы?","uz":"Dastlab ishchi kuchida 2,4 mln band, ish faol qidirayotgan 0,3 mln ishsiz; yana 0,5 mln faol bo‘lmaganlar bor. So‘ng ishsizlarning 0,1 mln qismi ish qidirishni to‘xtatadi, hech kim ishga joylashmaydi. O‘lchanadigan ishsizlik darajasi qanday o‘zgaradi?","options_en":["Stays at 11.1%","Rises from 11.1% to 12.5%","Falls from 9.4% to 6.3%","Falls from 11.1% to approximately 7.7%"],"options_ru":["Останется 11,1%","Вырастет с 11,1% до 12,5%","Снизится с 9,4% до 6,3%","Снизится с 11,1% примерно до 7,7%"],"options_uz":["11,1% bo‘lib qoladi","11,1% dan 12,5% ga oshadi","9,4% dan 6,3% ga tushadi","11,1% dan taxminan 7,7% ga tushadi"],"why":["Initially unemployment = 0.3/(2.4+0.3) ≈ 11.1%. Afterwards active unemployed = 0.2 and labour force = 2.6; rate ≈ 0.2/2.6 = 7.7%.","Изначально 0,3/(2,4+0,3) ≈ 11,1%. После выхода 0,1 млн из рабочей силы: 0,2/2,6 ≈ 7,7%, несмотря на отсутствие новых рабочих мест.","Dastlab 0,3/(2,4+0,3) ≈ 11,1%. Keyin ishsiz 0,2, ishchi kuchi 2,6; ko‘rsatkich 0,2/2,6 ≈ 7,7%, bandlik oshmagan bo‘lsa ham."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-006","d":"medium","sec":140,"k":"C","en":"A factory replaces routine jobs with software, leaving some former staff unable to meet new vacancy requirements even though spending on its products has recovered. Which pairing correctly identifies the unemployment and the most targeted response?","ru":"Завод автоматизировал рутинные рабочие места. Часть бывших работников не соответствует требованиям новых вакансий, хотя спрос на продукцию уже восстановился. Какая пара верно определяет безработицу и адресную меру?","uz":"Zavod oddiy ishlarni dasturiy ta’minotga almashtirdi. Mahsulotga talab tiklangan bo‘lsa ham, sobiq ishchilar yangi vakansiyalar malakasiga mos kelmayapti. Qaysi juftlik ishsizlik turini va mos chorasini to‘g‘ri ko‘rsatadi?","options_en":["Cyclical unemployment; only general demand stimulus","Seasonal unemployment; extend tourism seasons","Structural unemployment; skills retraining for new roles","Frictional unemployment; ban all job switching"],"options_ru":["Циклическая; только общее стимулирование спроса","Сезонная; продление туристического сезона","Структурная; переподготовка под новые профессии","Фрикционная; запрет переходов между работами"],"options_uz":["Davriy ishsizlik; faqat umumiy talabni rag‘batlantirish","Mavsumiy ishsizlik; sayyohlik mavsumini uzaytirish","Tarkibiy ishsizlik; yangi kasblarga qayta o‘qitish","Friksion ishsizlik; ish almashtirishni taqiqlash"],"why":["The skills mismatch persists after demand recovery, indicating structural rather than cyclical unemployment. Retraining addresses the mechanism.","Несоответствие навыков сохраняется после восстановления спроса: это структурная безработица, требующая переподготовки.","Talab tiklangandan keyin ham malaka mos kelmasligi tarkibiy ishsizlikdir; qayta tayyorlash muammoni nishonga oladi."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-020","d":"medium","sec":135,"k":"C","en":"A shipyard has two types of unemployed workers: group A lost jobs because welding was automated and their skills do not match new programming vacancies; group B has the necessary skills but was laid off temporarily when overall orders fell. Which pair identifies the MAIN causes for A and B?","ru":"На верфи без работы остались две группы. Группа A потеряла места из-за автоматизации сварки и не соответствует новым вакансиям программистов. Группа B обладает нужными навыками, но временно уволена из-за общего падения заказов. Какие причины безработицы у A и B?","uz":"Kemasozlik zavodida ikki guruh ishsiz. A guruhi payvandlash avtomatlashtirilgani va yangi dasturlash vakansiyalariga malakasi mos emasligi sabab ishsiz qoldi. B guruhi malakali, lekin umumiy buyurtmalar kamaygani uchun vaqtincha bo‘shatildi. A va B sabablarini belgilang.","options_en":["A cyclical; B structural","A frictional; B seasonal","A structural; B cyclical","A seasonal; B frictional"],"options_ru":["A — циклическая; B — структурная","A — фрикционная; B — сезонная","A — структурная; B — циклическая","A — сезонная; B — фрикционная"],"options_uz":["A — davriy; B — tarkibiy","A — friksion; B — mavsumiy","A — tarkibiy; B — davriy","A — mavsumiy; B — friksion"],"why":["A''s lasting skill mismatch is structural unemployment; B''s job loss from temporarily weak aggregate demand is cyclical.","У A устойчивое несоответствие квалификации — структурная безработица; у B временный недостаток спроса — циклическая.","A ning malaka mos kelmasligi tarkibiy ishsizlik; B dagi vaqtinchalik talab pasayishi davriy ishsizlik."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-026","d":"medium","sec":135,"k":"B","en":"Hotel staff are laid off during a broad recession, although their skills still fit their previous jobs and the hotel remains open. Tourism spending is expected to recover. Which classification and likely recovery mechanism fit best?","ru":"Во время общей рецессии гостиница увольняет сотрудников, хотя их квалификация подходит прежним обязанностям и гостиница продолжает работать. Ожидается восстановление туристических расходов. Какая пара «тип безработицы — механизм восстановления» лучше подходит?","uz":"Umumiy tanazzulda mehmonxona xodimlarni bo‘shatadi, ularning malakasi avvalgi ishga mos, mehmonxona ochiq. Turizm xarajatlari tiklanishi kutiladi. Qaysi «ishsizlik turi — tiklanish sababi» juftligi mos?","options_en":["Structural; permanent skill replacement","Cyclical; recovery of aggregate spending","Seasonal; fixed annual holiday closure","Frictional; workers voluntarily switch jobs"],"options_ru":["Структурная; необратимая замена навыков","Циклическая; восстановление совокупных расходов","Сезонная; регулярное закрытие на каникулы","Фрикционная; добровольная смена работодателя"],"options_uz":["Tarkibiy; malakani doimiy almashtirish","Davriy; jami xarajatlar tiklanishi","Mavsumiy; har yili ta’til sabab yopilish","Friksion; ixtiyoriy ish almashish"],"why":["Workers'' skills remain suitable; unemployment stems from reduced demand during recession and can ease as spending recovers.","Навыки работников сохраняют актуальность; причина — падение спроса в рецессию, которое может устраниться при восстановлении расходов.","Xodimlar malakasi mos, muammo tanazzuldagi talab pasayishidir; xarajat tiklansa bandlik ham tiklanishi mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-035","d":"medium","sec":130,"k":"C","en":"A region has two villages with identical medical needs. The richer village has a private clinic; the poorer village cannot afford travel to it. Government opens a local clinic in the poorer village. Which two objectives are most directly linked to this policy?","ru":"У двух деревень одинаковые медицинские потребности. В более богатой есть частная клиника, жители бедной не могут оплатить дорогу к ней. Государство открывает клинику в бедной деревне. Какие две цели наиболее непосредственно связаны с этой политикой?","uz":"Ikki qishloqning tibbiy ehtiyoji bir xil. Boyroq qishloqda xususiy klinika bor, kambag‘al qishloq aholisi u yerga yo‘l xarajatini qoplay olmaydi. Davlat kambag‘al qishloqda klinika ochdi. Qaysi ikki maqsad bevosita ko‘zlanadi?","options_en":["Maximise export earnings and raise tax revenue","Reduce money supply and raise interest rates","Improve geographical access and reduce inequality in service use","Protect a domestic monopoly and restrict supply"],"options_ru":["Максимизация экспорта и увеличение налогов","Сокращение денежной массы и рост ставок","Улучшение территориальной доступности и сокращение неравенства в получении услуг","Защита монополии и ограничение предложения"],"options_uz":["Eksport tushumini va soliqlarni oshirish","Pul massasini kamaytirib, foizni oshirish","Hududiy kirishni yaxshilash va xizmatlardan foydalanish tengsizligini kamaytirish","Mahalliy monopoliyani himoya qilish va taklifni cheklash"],"why":["Public provision directly reduces a geographic and affordability barrier to care, serving an equity objective.","Государственное предоставление услуги устраняет территориальный и финансовый барьер, поддерживая справедливость доступа.","Davlat taqdimoti tibbiy xizmatdagi geografik hamda moliyaviy to‘siqlarni kamaytirib, tenglikka xizmat qiladi."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-040","d":"medium","sec":145,"k":"D","en":"Global fuel prices fall, reducing a widespread input cost for domestic firms. With aggregate demand and productive technology unchanged, which pair of short-run AD–AS effects is most plausible?","ru":"Мировые цены на топливо падают, уменьшая распространённые производственные издержки внутренних фирм. При неизменных AD и технологиях какая пара краткосрочных эффектов AD–AS наиболее вероятна?","uz":"Jahon yoqilg‘i narxi pasayib, mahalliy firmalarning keng tarqalgan ishlab chiqarish xarajatini kamaytiradi. Yalpi talab va texnologiya o‘zgarmasa, qisqa muddatli AD–AS da qaysi juftlik eng ehtimolli?","options_en":["SRAS shifts left; prices rise and output falls","AD shifts right; prices and output necessarily rise","LRAS shifts left immediately; output falls","SRAS shifts right; price level falls and real output rises"],"options_ru":["SRAS влево; цены растут, выпуск падает","AD вправо; цены и выпуск обязательно растут","LRAS немедленно влево; выпуск падает","SRAS вправо; уровень цен падает, реальный выпуск растёт"],"options_uz":["SRAS chapga; narx oshadi, ishlab chiqarish kamayadi","AD o‘ngga; narx va ishlab chiqarish albatta oshadi","LRAS darhol chapga; ishlab chiqarish kamayadi","SRAS o‘ngga; narx pasayadi, real ishlab chiqarish oshadi"],"why":["Lower input costs shift SRAS right, allowing greater real output at a lower price level, all else equal.","Падение издержек сдвигает SRAS вправо, позволяя больший выпуск при более низком уровне цен.","Xarajatlar pasayishi SRAS ni o‘ngga suradi, real ishlab chiqarish oshib, narx darajasi pasayadi."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-043","d":"medium","sec":145,"k":"A","en":"A pension is fixed at $1,000 a month while prices rise so the CPI moves from 100 to 125. Other workers have wages indexed exactly to inflation. What is the pension''s new purchasing power in base-period dollars, and what happens to indexed real wages?","ru":"Пенсия фиксирована на $1 000 в месяц, а индекс цен вырос со 100 до 125. Зарплаты остальных работников точно индексируются по инфляции. Чему равна покупательная способность пенсии в долларах базового периода и что происходит с реальной индексированной зарплатой?","uz":"Pensiya oyiga $1000 qat’iy, narx indeksi 100 dan 125 ga oshdi. Boshqa ishchilarning maoshi inflyatsiyaga to‘liq indeksatsiya qilingan. Pensiyaning bazis davr dollaridagi xarid quvvati qancha va indekslangan real ish haqi qanday o‘zgaradi?","options_en":["$800; indexed real wages are unchanged","$1,250; indexed real wages rise 25%","$750; indexed real wages fall 25%","$1,000; indexed real wages are unchanged"],"options_ru":["$800; реальная индексированная зарплата неизменна","$1 250; реальная индексированная зарплата растёт на 25%","$750; реальная индексированная зарплата падает на 25%","$1 000; реальная индексированная зарплата неизменна"],"options_uz":["$800; indekslangan real ish haqi o‘zgarmaydi","$1250; indekslangan real ish haqi 25% oshadi","$750; indekslangan real ish haqi 25% kamayadi","$1000; indekslangan real ish haqi o‘zgarmaydi"],"why":["The fixed pension''s real value is $1,000 × 100/125 = $800. Full wage indexation preserves real purchasing power.","Фиксированная пенсия в реальном выражении $1 000 × 100/125 = $800. Полная индексация зарплат сохраняет их реальную ценность.","Qat’iy pensiyaning real qiymati $1000 × 100/125 = $800. To‘liq indeksatsiya real ish haqini saqlaydi."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-050","d":"medium","sec":140,"k":"A","en":"An economy''s CPI basket assigns 60% of expenditure weight to food and 40% to clothing. Food prices rise 10% while clothing prices fall 5%; assume fixed quantities and no other items. Approximately how much does this basket-based CPI rise?","ru":"В корзине CPI на продовольствие приходится 60% расходов, на одежду — 40%. Продовольствие подорожало на 10%, одежда подешевела на 5%; объёмы и прочие товары неизменны. На сколько примерно вырос индекс цен такой корзины?","uz":"CPI savatida oziq-ovqat xarajatlari 60%, kiyim esa 40%. Oziq-ovqat narxi 10% oshdi, kiyim narxi 5% tushdi; miqdorlar o‘zgarmaydi va boshqa mahsulot yo‘q. Ushbu savat CPI taxminan nechaga oshadi?","options_en":["+4%","+6%","+5%","−4%"],"options_ru":["+4%","+6%","+5%","−4%"],"options_uz":["+4%","+6%","+5%","−4%"],"why":["With fixed basket weights, the combined price change is 0.6×10% + 0.4×(−5%) = 6% − 2% = +4%.","При фиксированных весах изменение CPI: 0,6×10% + 0,4×(−5%) = 6% − 2% = +4%.","O‘zgarmas vaznda CPI o‘zgarishi 0,6×10% + 0,4×(−5%) = 6% − 2% = +4%."]},{"ref":"EC9708:G2:EC9708-G2-T2-P-067","d":"medium","sec":150,"k":"C","en":"An employee''s nominal salary rises by 4% over a year, while the consumer price index rises by 7%. Using the exact ratio of salary and price indices, approximately how much does the employee''s real purchasing power change?","ru":"Номинальная зарплата за год выросла на 4%, индекс потребительских цен — на 7%. Используя точное отношение индексов зарплаты и цен, оцените изменение реальной покупательной способности работника.","uz":"Xodimning nominal ish haqi yiliga 4%, iste’mol narxlari indeksi esa 7% oshdi. Ish haqi va narx indekslarining aniq nisbatidan foydalanib, real xarid quvvati taxminan qanday o‘zgargan?","options_en":["+3.0%","−3.0%","−2.8%","+2.8%"],"options_ru":["+3,0%","−3,0%","−2,8%","+2,8%"],"options_uz":["+3,0%","−3,0%","−2,8%","+2,8%"],"why":["Real income factor = 1.04/1.07 ≈ 0.97196, so purchasing power falls by about 2.8%.","Коэффициент реального дохода 1,04/1,07 ≈ 0,97196, поэтому покупательная способность падает примерно на 2,8%.","Real daromad koeffitsienti 1,04/1,07 ≈ 0,97196, xarid quvvati taxminan 2,8% kamayadi."]}]'::jsonb;
  item jsonb; v_old bigint; v_new bigint; v_pool bigint; v_order int; v_count int;
  v_correct text; v_i int; v_why_en text; v_why_ru text; v_why_uz text; v_old_key text;
  v_saved_answers int;
BEGIN
  IF jsonb_array_length(payload) <> 28 THEN RAISE EXCEPTION 'expected_28_replacements'; END IF;
  SELECT count(*) INTO v_count FROM public.practice_pool_questions l
    JOIN public.practice_pools p ON p.id=l.pool_id WHERE p.subject_id=7 AND p.tour_no=2 AND l.is_active;
  IF v_count <> 70 THEN RAISE EXCEPTION 'T2_pool_not_70_before: %',v_count; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(payload)
  LOOP
    v_old_key := item->>'ref'; v_correct := item->>'k';
    IF jsonb_array_length(item->'options_en')<>4 OR jsonb_array_length(item->'options_ru')<>4 OR jsonb_array_length(item->'options_uz')<>4 THEN
      RAISE EXCEPTION 'four_options_required: %',v_old_key;
    END IF;
    IF v_correct NOT IN ('A','B','C','D') OR item->>'d' NOT IN ('medium','hard') THEN RAISE EXCEPTION 'invalid_authoring: %',v_old_key; END IF;
    SELECT q.id INTO STRICT v_old FROM public.questions q WHERE q.subject_id=7 AND q.book_ref=v_old_key;
    SELECT count(*) INTO v_saved_answers FROM public.practice_answers a WHERE a.question_id=v_old;
    IF v_saved_answers > 0 THEN RAISE EXCEPTION 'review_history_bearing_question_before_replacement: %',v_old_key; END IF;
    SELECT l.pool_id,l.order_no INTO STRICT v_pool,v_order FROM public.practice_pool_questions l
      JOIN public.practice_pools p ON p.id=l.pool_id
      WHERE l.question_id=v_old AND l.is_active AND p.subject_id=7 AND p.tour_no=2;
    SELECT id INTO v_new FROM public.questions WHERE subject_id=7 AND book_ref=v_old_key||'-V2';
    IF v_new IS NOT NULL THEN RAISE EXCEPTION 'already_exists: %',v_old_key; END IF;
    v_i := ascii(v_correct)-64;
    v_why_en := item->'why'->>0; v_why_ru := item->'why'->>1; v_why_uz := item->'why'->>2;
    INSERT INTO public.questions (
      subject_id,topic,subtopic,difficulty,qtype,
      question_text,options_text,correct_answer,explanation,image_url,is_active,
      question_text_ru,question_text_uz,question_text_en,
      options_text_ru,options_text_uz,options_text_en,
      explanation_ru,explanation_uz,explanation_en,
      book_ref,time_limit_sec,quality_flag,quality_status
    )
    SELECT
      src.subject_id,src.topic,src.subtopic,item->>'d','mcq',
      item->>'en',(item->'options_en')::text,v_correct,
      'Correct answer: '||(item->'options_en'->>(v_i-1))||E'\nWhy: '||v_why_en,
      NULL,true,item->>'ru',item->>'uz',item->>'en',
      (item->'options_ru')::text,(item->'options_uz')::text,(item->'options_en')::text,
      'Правильный ответ: '||(item->'options_ru'->>(v_i-1))||E'\nПочему: '||v_why_ru,
      'To‘g‘ri javob: '||(item->'options_uz'->>(v_i-1))||E'\nSabab: '||v_why_uz,
      'Correct answer: '||(item->'options_en'->>(v_i-1))||E'\nWhy: '||v_why_en,
      v_old_key||'-V2',(item->>'sec')::int,src.quality_flag,'published'
    FROM public.questions src WHERE src.id=v_old
    RETURNING id INTO v_new;
    UPDATE public.practice_pool_questions SET is_active=false
      WHERE pool_id=v_pool AND question_id=v_old AND is_active;
    GET DIAGNOSTICS v_count=ROW_COUNT;
    IF v_count<>1 THEN RAISE EXCEPTION 'old_link_not_one: %',v_old_key; END IF;
    INSERT INTO public.practice_pool_questions (pool_id,question_id,order_no,is_active)
      VALUES (v_pool,v_new,v_order,true);
    INSERT INTO public.question_version_links(old_question_id,new_question_id,link_type,reason)
      VALUES(v_old,v_new,'replacement','Economics Gen2: actual editorial difficulty upgrade, T2 governed practice, originals retained');
    FOR v_i IN 1..4 LOOP
      INSERT INTO public.question_answer_diagnostics(
        question_id,answer_kind,answer_key,answer_value,is_correct,
        mistake_type,weak_skill,feedback_ru,feedback_uz,feedback_en,
        next_action_ru,next_action_uz,next_action_en,rule_json,quality_status
      )
      SELECT v_new,'mcq_option',chr(64+v_i),NULL,(chr(64+v_i)=v_correct),
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'multi_step_economic_reasoning' END,
        src.subtopic,
        'Выбранный ответ: '||(item->'options_ru'->>(v_i-1))||E'\nОбъяснение: '||v_why_ru||E'\nПравильный ответ: '||(item->'options_ru'->>(ascii(v_correct)-65)),
        'Tanlangan javob: '||(item->'options_uz'->>(v_i-1))||E'\nIzoh: '||v_why_uz||E'\nTo‘g‘ri javob: '||(item->'options_uz'->>(ascii(v_correct)-65)),
        'Selected answer: '||(item->'options_en'->>(v_i-1))||E'\nReason: '||v_why_en||E'\nCorrect answer: '||(item->'options_en'->>(ascii(v_correct)-65)),
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Повторите метод решения и проверьте каждый шаг.' END,
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Yechim usulini takrorlang va har bir bosqichni tekshiring.' END,
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Review the method and check each step.' END,
        jsonb_build_object('diagnostic_code','EC9708_G2_T2P'||substring(v_old_key from 'P-([0-9]{3})')||'_V2_'||chr(64+v_i)),
        'published'
      FROM public.questions src WHERE src.id=v_old;
    END LOOP;
  END LOOP;
  -- Existing unchanged T2 items receive academically reviewed metadata, not fabricated all-medium labels.
  UPDATE public.questions q SET difficulty=CASE
    WHEN right(q.book_ref,3) IN ('001','008','009','011','015','017','022','025','028','030','033','034','037','042','045','046','053','056','061','062','063','070') THEN 'medium'
    ELSE 'easy' END
    WHERE q.subject_id=7 AND q.book_ref ~ '^EC9708:G2:EC9708-G2-T2-P-[0-9]{3}$'
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(payload) j WHERE j->>'ref'=q.book_ref);
  GET DIAGNOSTICS v_count=ROW_COUNT;
  IF v_count<>42 THEN RAISE EXCEPTION 'unchanged_count_expected42: %',v_count; END IF;
  SELECT count(*) INTO v_count FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    WHERE p.subject_id=7 AND p.tour_no=2 AND l.is_active;
  IF v_count<>70 THEN RAISE EXCEPTION 'active_pool_not70_after: %',v_count; END IF;
  IF EXISTS (
    SELECT 1 FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
       JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=2 AND l.is_active
    GROUP BY 1 HAVING count(*)<>70
  ) THEN RAISE EXCEPTION 'pool_count_inconsistent'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=2 AND l.is_active AND q.difficulty='easy') <> 20
    THEN RAISE EXCEPTION 'difficulty_easy_not20'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=2 AND l.is_active AND q.difficulty='medium') <> 30
    THEN RAISE EXCEPTION 'difficulty_medium_not30'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=2 AND l.is_active AND q.difficulty='hard') <> 20
    THEN RAISE EXCEPTION 'difficulty_hard_not20'; END IF;
END $reb$;
COMMIT;
